def count_element_freq(tup):
    freq = {}
    for item in tup:
        if isinstance(item, tuple):
            for sub_item in item:
                if sub_item in freq:
                    freq[sub_item] += 1
                else:
                    freq[sub_item] = 1
        else:
            if item in freq:
                freq[item] += 1
            else:
                freq[item] = 1
    return freq

